CREATE FUNCTION public.admin_find_account(p_actor uuid,p_query text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; BEGIN IF NOT has_role(p_actor,'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; SELECT id,email INTO r FROM auth.users WHERE id::text=p_query OR lower(email)=lower(p_query) LIMIT 1; IF NOT FOUND THEN RETURN null; END IF; RETURN jsonb_build_object('id',r.id,'email',r.email); END $$;
REVOKE ALL ON FUNCTION public.admin_find_account(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_find_account(uuid,text) TO service_role;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;